import React, { useState, useEffect } from "react";
import axios from "axios";
import {useCart} from '../components/CartContext';



const Products = () => {
  const [products, setProducts] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [file, setFile] = useState(null); // Image file state
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [showViewModal, setShowViewModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [categories, setCategories] = useState([]);
  const {addToCart}= useCart();

  useEffect(() => {
    const fetchCategories = async () => {
      try {
        const res = await axios.get("http://localhost:5000/api/users/allcategories");
        setCategories(res.data);
      } catch (err) {
        console.error("Error fetching categories", err);
      }
    };

    fetchCategories();
  }, []);
  const [brands, setBrands] = useState([]);

  useEffect(() => {
    const fetchBrands = async () => {
      try {
        const res = await axios.get("http://localhost:5000/api/users/allbrands");
        setBrands(res.data);
      } catch (err) {
        console.error("Error fetching brands", err);
      }
    };

    fetchBrands();
  }, []);


  const modalOverlayStyle = {
    position: "fixed",
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: "rgba(0,0,0,0.6)",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    zIndex: 1000,
  };

  const modalContentStyle = {
    backgroundColor: "#fff",
    padding: "20px",
    borderRadius: "10px",
    maxWidth: "400px",
    width: "90%",
    boxShadow: "0 5px 15px rgba(0,0,0,0.3)",
    textAlign: "center",
  };




  const [formData, setFormData] = useState({
    name: "",
    category: "",
    price: "",
    brand: "",
  });

  //  Fetch products from backend
  useEffect(() => {
    const fetchProducts = async () => {
      try {
        const res = await axios.get("http://localhost:5000/api/users/allproducts");
        setProducts(res.data);
      } catch (err) {
        console.error("Error fetching products:", err);
      }
    };
    fetchProducts();
  }, []);

  // Handle text input changes
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  // Handle image input
  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  //  Add product to backend
  const handleAddProduct = async (e) => {
    e.preventDefault();

    const formDataToSend = new FormData();
    formDataToSend.append("name", formData.name);
    formDataToSend.append("category", formData.category);
    formDataToSend.append("price", formData.price);
    formDataToSend.append("brand", formData.brand);
    formDataToSend.append("image", file); //  actual image file

    try {
      const res = await axios.post("http://localhost:5000/api/users/addproduct", formDataToSend, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });

      setProducts([res.data, ...products]); // Add new product to UI
      setFormData({ name: "", category: "", price: "", brand: "" });
      setFile(null);
      setShowForm(false);
    } catch (err) {
      console.error(" Failed to add product:", err);
      alert(err.response?.data?.message || "Error adding product");
    }
  };
  const handleDelete = async (id) => {
    if (!window.confirm("Are you sure you want to delete this product?")) return;

    try {
      await axios.delete("http:localhost:5000/api/users/product/${id}");
      setProducts(products.filter((p) => p._id !== id));
    } catch (err) {
      console.error(" Failed to delete:", err);
      alert("Failed to delete product");
    }
  };


  const DropdownWithRadios = ({ title, options, selected, setSelected, icon }) => {
    const [isOpen, setIsOpen] = useState(false);
    const toggleDropdown = () => setIsOpen(!isOpen);

    return (
      <div style={{ display: 'inline-block', position: 'relative', zIndex: 100 }}>
        <button
          onClick={toggleDropdown}
          className="btn"
          style={{
            backgroundColor: 'white',
            border: '2px solid #e9ecef',
            borderRadius: '12px',
            padding: '12px 20px',
            fontSize: '14px',
            fontWeight: 600,
            minWidth: '130px',
            height: '45px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: '8px',
            cursor: 'pointer',
            transition: 'all 0.3s ease',
            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.05)',
            outline: 'none',
          }}
          onMouseEnter={(e) => {
            e.target.style.borderColor = '#007bff';
            e.target.style.boxShadow = '0 0 0 3px rgba(0, 123, 255, 0.1)';
          }}
          onMouseLeave={(e) => {
            e.target.style.borderColor = '#e9ecef';
            e.target.style.boxShadow = '0 2px 8px rgba(0, 0, 0, 0.05)';
          }}
        >
          {title}
          {icon ? <span style={{ fontSize: '16px' }}>{icon}</span> : <span style={{ fontSize: '10px' }}>▼</span>}
        </button>
        {isOpen && (
          <div
            className="dropdown-in"
            style={{
              position: 'absolute',
              top: '110%',
              left: 0,
              backgroundColor: '#fff',
              zIndex: 9999,
              borderRadius: '12px',
              maxHeight: '350px',
              overflowY: 'auto',
              padding: '15px',
              width: '260px',
              border: '2px solid #e9ecef',
              boxShadow: '0 8px 25px rgba(0, 0, 0, 0.15)',
              marginTop: '8px',
              backdropFilter: 'blur(10px)',
            }}
            onMouseLeave={() => setIsOpen(false)}
          >
            {title === "Category" && (
              <ol style={{ margin: 0, paddingLeft: 0, listStyle: "none" }}>
                {categories.map((cat, i) => (
                  <li key={i}>
                    <label
                      style={{
                        display: "flex",
                        alignItems: "center",
                        padding: "8px 12px",
                        cursor: "pointer",
                        borderRadius: "8px",
                        transition: "background-color 0.2s ease",
                        marginBottom: "4px",
                      }}
                      onMouseEnter={(e) => (e.target.style.backgroundColor = "#f8f9fa")}
                      onMouseLeave={(e) => (e.target.style.backgroundColor = "transparent")}
                    >
                      <input
                        type="radio"
                        name={title.toLowerCase()}
                        value={cat.name}
                        checked={selected === cat.name}
                        onChange={(e) => setSelected(e.target.value)}
                        style={{ marginRight: "10px", accentColor: "#007bff" }}
                      />
                      {cat.name}
                    </label>
                  </li>
                ))}
              </ol>
            )}
            {title === "Brand" && (
              <ol style={{ margin: 0, paddingLeft: 0, listStyle: "none" }}>
                {brands.map((cat, i) => (
                  <li key={i}>
                    <label
                      style={{
                        display: "flex",
                        alignItems: "center",
                        padding: "8px 12px",
                        cursor: "pointer",
                        borderRadius: "8px",
                        transition: "background-color 0.2s ease",
                        marginBottom: "4px",
                      }}
                      onMouseEnter={(e) => (e.target.style.backgroundColor = "#f8f9fa")}
                      onMouseLeave={(e) => (e.target.style.backgroundColor = "transparent")}
                    >
                      <input
                        type="radio"
                        name={title.toLowerCase()}
                        value={cat.name}
                        checked={selected === cat.name}
                        onChange={(e) => setSelected(e.target.value)}
                        style={{ marginRight: "10px", accentColor: "#007bff" }}
                      />
                      {cat.name}
                    </label>
                  </li>
                ))}
              </ol>
            )}
            {title === "Price" && (
              <ol style={{ margin: 0, paddingLeft: 0, listStyle: "none" }}>
                {/* Add/remove price options here */}
                <li><label style={{ display: "flex", alignItems: "center", padding: "8px 12px", cursor: "pointer", borderRadius: "8px", transition: "background-color 0.2s ease", marginBottom: "4px" }} onMouseEnter={(e) => e.target.style.backgroundColor = "#f8f9fa"} onMouseLeave={(e) => e.target.style.backgroundColor = "transparent"}><input type="radio" name={title.toLowerCase()} value="0-1000" checked={selected === "0-1000"} onChange={(e) => setSelected(e.target.value)} style={{ marginRight: "10px", accentColor: "#007bff" }} /> ₹0 - ₹100</label></li>
                <li><label style={{ display: "flex", alignItems: "center", padding: "8px 12px", cursor: "pointer", borderRadius: "8px", transition: "background-color 0.2s ease", marginBottom: "4px" }} onMouseEnter={(e) => e.target.style.backgroundColor = "#f8f9fa"} onMouseLeave={(e) => e.target.style.backgroundColor = "transparent"}><input type="radio" name={title.toLowerCase()} value="1000-1500" checked={selected === "1000-1500"} onChange={(e) => setSelected(e.target.value)} style={{ marginRight: "10px", accentColor: "#007bff" }} /> ₹1000 - ₹1500</label></li>
                <li><label style={{ display: "flex", alignItems: "center", padding: "8px 12px", cursor: "pointer", borderRadius: "8px", transition: "background-color 0.2s ease", marginBottom: "4px" }} onMouseEnter={(e) => e.target.style.backgroundColor = "#f8f9fa"} onMouseLeave={(e) => e.target.style.backgroundColor = "transparent"}><input type="radio" name={title.toLowerCase()} value="1500-2000" checked={selected === "1500-2000"} onChange={(e) => setSelected(e.target.value)} style={{ marginRight: "10px", accentColor: "#007bff" }} /> ₹1500 - ₹2000</label></li>
                <li><label style={{ display: "flex", alignItems: "center", padding: "8px 12px", cursor: "pointer", borderRadius: "8px", transition: "background-color 0.2s ease", marginBottom: "4px" }} onMouseEnter={(e) => e.target.style.backgroundColor = "#f8f9fa"} onMouseLeave={(e) => e.target.style.backgroundColor = "transparent"}><input type="radio" name={title.toLowerCase()} value="2000-3000" checked={selected === "2000-3000"} onChange={(e) => setSelected(e.target.value)} style={{ marginRight: "10px", accentColor: "#007bff" }} /> ₹2000 - ₹3000</label></li>
                <li><label style={{ display: "flex", alignItems: "center", padding: "8px 12px", cursor: "pointer", borderRadius: "8px", transition: "background-color 0.2s ease", marginBottom: "4px" }} onMouseEnter={(e) => e.target.style.backgroundColor = "#f8f9fa"} onMouseLeave={(e) => e.target.style.backgroundColor = "transparent"}><input type="radio" name={title.toLowerCase()} value="3000+" checked={selected === "3000+"} onChange={(e) => setSelected(e.target.value)} style={{ marginRight: "10px", accentColor: "#007bff" }} /> ₹3000+</label></li>
              </ol>
            )}
          </div>
        )}
      </div>
    );
  };

  // Add state for filter selections
  const [categoryFilter, setCategoryFilter] = useState("");
  const [brandFilter, setBrandFilter] = useState("");
  const [priceFilter, setPriceFilter] = useState("");

  const filteredProducts = products.filter((product) => {
    const matchesSearch = product.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = categoryFilter ? product.category.toLowerCase() === categoryFilter.toLowerCase() : true;
    const matchesBrand = brandFilter ? product.brand.toLowerCase() === brandFilter.toLowerCase() : true;
    const matchesPrice = (() => {
      if (!priceFilter) return true;
      const price = Number(product.price);
      if (priceFilter === "0-1000") return price >= 0 && price <= 1000;
      if (priceFilter === "1000-1500") return price > 1000 && price <= 1500;
      if (priceFilter === "1500-2000") return price > 1500 && price <= 2000;
      if (priceFilter === "2000-3000") return price > 2000 && price <= 3000;
      if (priceFilter === "3000+") return price > 3000;
      return true;
    })();

    return matchesSearch && matchesCategory && matchesBrand && matchesPrice;
  });


  return (
    <div style={{ backgroundColor: "white" }}>
      <h1 style={{ textAlign: "center", marginTop: "0px", marginBottom: '0px' }}>PRODUCTS</h1>
      <div className="filterbar" style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        gap: "15px",
        margin: "30px auto",
        padding: "25px 30px",
        backgroundColor: "#f8f9fa",
        borderRadius: "15px",
        boxShadow: "none",
        border: "1px solid white",
        maxWidth: "1200px",
        flexWrap: "wrap",
        position: "relative",
        backdropFilter: "blur(10px)",
      }}>
        <DropdownWithRadios
          title="Category"
          options={[]}
          selected={categoryFilter}
          setSelected={setCategoryFilter}
          icon="▼"
        />
        <DropdownWithRadios
          title="Brand"
          options={[]}
          selected={brandFilter}
          setSelected={setBrandFilter}
          icon="▼"
        />
        <DropdownWithRadios
          title="Price"
          options={[]}
          selected={priceFilter}
          setSelected={setPriceFilter}
          icon="▼"
        />
        <input
          className="search"
          type="text"
          placeholder="Search products..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{
            backgroundColor: 'white',
            borderRadius: '12px',
            padding: '12px 20px',
            width: '400px',
            height: '20px',
            border: '2px solid #e9ecef',
            fontSize: '14px',
            outline: 'none',
            transition: 'all 0.3s ease',
            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.05)',
          }}
          onFocus={(e) => {
            e.target.style.borderColor = '#007bff';
            e.target.style.boxShadow = '0 0 0 3px rgba(0, 123, 255, 0.1)';
          }}
          onBlur={(e) => {
            e.target.style.borderColor = '#e9ecef';
            e.target.style.boxShadow = '0 2px 8px rgba(0, 0, 0, 0.05)';
          }}
        />

        <button
          onClick={() => {
            setCategoryFilter("");
            setBrandFilter("");
            setPriceFilter("");
            setSearchTerm("");
          }}
          style={{
            backgroundColor: '#6c757d',
            color: 'white',
            border: 'none',
            borderRadius: '12px',
            padding: '12px 24px',
            fontSize: '14px',
            fontWeight: 600,
            minWidth: '130px',
            height: '45px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '8px',
            cursor: 'pointer',
            transition: 'all 0.3s ease',
            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.1)',
          }}
          onMouseEnter={(e) => {
            e.target.style.backgroundColor = '#5a6268';
            e.target.style.transform = 'translateY(-2px)';
            e.target.style.boxShadow = '0 4px 12px rgba(0, 0, 0, 0.15)';
          }}
          onMouseLeave={(e) => {
            e.target.style.backgroundColor = '#6c757d';
            e.target.style.transform = 'translateY(0)';
            e.target.style.boxShadow = '0 2px 8px rgba(0, 0, 0, 0.1)';
          }}
        >
          Reset Filter
        </button>


        {/* Add Product Button */}

        <button style={{
          backgroundColor: '#28a745',
          color: 'white',
          border: 'none',
          borderRadius: '12px',
          padding: '12px 24px',
          fontSize: '14px',
          fontWeight: 600,
          minWidth: '130px',
          height: '45px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: '8px',
          cursor: 'pointer',
          transition: 'all 0.3s ease',
          boxShadow: '0 2px 8px rgba(40, 167, 69, 0.2)',
        }}
          onClick={() => setShowForm(true)}
          onMouseEnter={(e) => {
            e.target.style.backgroundColor = '#218838';
            e.target.style.transform = 'translateY(-2px)';
            e.target.style.boxShadow = '0 4px 12px rgba(40, 167, 69, 0.3)';
          }}
          onMouseLeave={(e) => {
            e.target.style.backgroundColor = '#28a745';
            e.target.style.transform = 'translateY(0)';
            e.target.style.boxShadow = '0 2px 8px rgba(40, 167, 69, 0.2)';
          }}
        >
          <span style={{ fontSize: '16px', marginRight: '4px' }}>+</span>
          Add Product
        </button>

      </div>



      {/*  Modal Form */}
      {showForm && (
        <div style={{
          position: "fixed",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: "rgba(0,0,0,0.6)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          zIndex: 1000,
          backdropFilter: "blur(5px)",
        }}>
          <div className="fade-in" style={{
            backgroundColor: "#fff",
            padding: "30px",
            borderRadius: "15px",
            maxWidth: "500px",
            width: "90%",
            boxShadow: "0 10px 30px rgba(0,0,0,0.3)",
            position: "relative",
          }}>
            <h2 style={{
              textAlign: "center",
              marginBottom: "25px",
              color: "#333",
              fontSize: "24px",
              fontWeight: "600",
            }}>Add New Product</h2>
            <form onSubmit={handleAddProduct} encType="multipart/form-data" style={{
              display: "flex",
              flexDirection: "column",
              gap: "15px",
            }}>
              <input
                type="text"
                name="name"
                placeholder="Product Name"
                value={formData.name}
                onChange={handleChange}
                required
                style={{
                  padding: "12px 16px",
                  borderRadius: "8px",
                  border: "2px solid #e9ecef",
                  fontSize: "14px",
                  outline: "none",
                  transition: "all 0.3s ease",
                }}
                onFocus={(e) => {
                  e.target.style.borderColor = "#007bff";
                  e.target.style.boxShadow = "0 0 0 3px rgba(0, 123, 255, 0.1)";
                }}
                onBlur={(e) => {
                  e.target.style.borderColor = "#e9ecef";
                  e.target.style.boxShadow = "none";
                }}
              />
              <select
                name="category"
                value={formData.category}
                onChange={handleChange}
                required
                style={{
                  padding: "12px 16px",
                  borderRadius: "8px",
                  border: "2px solid #e9ecef",
                  fontSize: "14px",
                  outline: "none",
                  transition: "all 0.3s ease",
                }}
                onFocus={(e) => {
                  e.target.style.borderColor = "#007bff";
                  e.target.style.boxShadow = "0 0 0 3px rgba(0, 123, 255, 0.1)";
                }}
                onBlur={(e) => {
                  e.target.style.borderColor = "#e9ecef";
                  e.target.style.boxShadow = "none";
                }}
              >
                <option value="" disabled>Select Category</option>
                {categories.map((cat) => (
                  <option key={cat._id} value={cat.name}>{cat.name}</option>
                ))}
              </select>

              <select
                name="brand"
                value={formData.brand}
                onChange={handleChange}
                required
                style={{
                  padding: "12px 16px",
                  borderRadius: "8px",
                  border: "2px solid #e9ecef",
                  fontSize: "14px",
                  outline: "none",
                  transition: "all 0.3s ease",
                }}
                onFocus={(e) => {
                  e.target.style.borderColor = "#007bff";
                  e.target.style.boxShadow = "0 0 0 3px rgba(0, 123, 255, 0.1)";
                }}
                onBlur={(e) => {
                  e.target.style.borderColor = "#e9ecef";
                  e.target.style.boxShadow = "none";
                }}
              >
                <option value="" disabled>Select brand</option>
                {brands.map((cat) => (
                  <option key={cat._id} value={cat.name}>{cat.name}</option>
                ))}
              </select>


              <input
                type="number"
                name="price"
                placeholder="Price"
                value={formData.price}
                onChange={handleChange}
                required
                style={{
                  padding: "12px 16px",
                  borderRadius: "8px",
                  border: "2px solid #e9ecef",
                  fontSize: "14px",
                  outline: "none",
                  transition: "all 0.3s ease",
                }}
                onFocus={(e) => {
                  e.target.style.borderColor = "#007bff";
                  e.target.style.boxShadow = "0 0 0 3px rgba(0, 123, 255, 0.1)";
                }}
                onBlur={(e) => {
                  e.target.style.borderColor = "#e9ecef";
                  e.target.style.boxShadow = "none";
                }}
              />

              <div style={{
                border: "2px dashed #e9ecef",
                borderRadius: "8px",
                padding: "20px",
                textAlign: "center",
                transition: "all 0.3s ease",
                cursor: "pointer",
              }}
                onMouseEnter={(e) => {
                  e.target.style.borderColor = "#007bff";
                  e.target.style.backgroundColor = "#f8f9fa";
                }}
                onMouseLeave={(e) => {
                  e.target.style.borderColor = "#e9ecef";
                  e.target.style.backgroundColor = "transparent";
                }}>
                <input
                  type="file"
                  name="image"
                  accept="image/*"
                  onChange={handleFileChange}
                  required
                  style={{
                    width: "100%",
                    cursor: "pointer",
                  }}
                />
                <p style={{
                  margin: "10px 0 0 0",
                  color: "#6c757d",
                  fontSize: "12px",
                }}>Click to upload product image</p>
              </div>
              <div style={{
                display: "flex",
                gap: "15px",
                marginTop: "10px",
              }}>
                <button
                  type="submit"
                  style={{
                    flex: 1,
                    backgroundColor: "#28a745",
                    color: "white",
                    border: "none",
                    borderRadius: "8px",
                    padding: "12px 20px",
                    fontSize: "14px",
                    fontWeight: "600",
                    cursor: "pointer",
                    transition: "all 0.3s ease",
                  }}
                  onMouseEnter={(e) => {
                    e.target.style.backgroundColor = "#218838";
                    e.target.style.transform = "translateY(-1px)";
                  }}
                  onMouseLeave={(e) => {
                    e.target.style.backgroundColor = "#28a745";
                    e.target.style.transform = "translateY(0)";
                  }}
                >
                  Submit
                </button>
                <button
                  type="button"
                  style={{
                    flex: 1,
                    backgroundColor: "#6c757d",
                    color: "white",
                    border: "none",
                    borderRadius: "8px",
                    padding: "12px 20px",
                    fontSize: "14px",
                    fontWeight: "600",
                    cursor: "pointer",
                    transition: "all 0.3s ease",
                  }}
                  onClick={() => setShowForm(false)}
                  onMouseEnter={(e) => {
                    e.target.style.backgroundColor = "#5a6268";
                    e.target.style.transform = "translateY(-1px)";
                  }}
                  onMouseLeave={(e) => {
                    e.target.style.backgroundColor = "#6c757d";
                    e.target.style.transform = "translateY(0)";
                  }}
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/*  Product Cards Grid */}
      {/*  Product Cards Grid */}
      <div className="product-grid">
        {filteredProducts.map((product, index) => (
          <div key={index} className="square-card">


            <img
              src={`http://localhost:5000/uploads/${product.image}`}
              alt={product.name}
              className="square-img"
            />
            <div className="square-info">
              <h4>{product.name}</h4>
              <p className="product-meta">{product.category}</p>
              <p className="product-meta">₹{product.price}</p>
              <p className="product-meta">{product.brand}</p>
            </div>
            <div className="button-row">
              <button className="square-btn delete" onClick={() => handleDelete(product._id)}>
                Delete
              </button>

              <button
                className="square-btn view"
                onClick={() => {
                  setSelectedProduct(product);
                  setShowViewModal(true);
                }}
              >
                View
              </button>
              <button style={{backgroundColor : ''}} onClick={() => addToCart(product)}>Add to Cart</button>
            </div>
          </div>
        ))}
      </div>
      {/* Product Details Modal (rendered once, outside the map) */}
      {showViewModal && selectedProduct && (
        <div className="modal-overlay fade-in" style={modalOverlayStyle}>
          <div className="modal-content" style={modalContentStyle}>
            <h2>Product Details</h2>
            <img
              src={`http://localhost:5000/uploads/${selectedProduct.image}`}
              alt={selectedProduct.name}
              style={{ width: "100%", maxHeight: "250px", objectFit: "cover", borderRadius: "10px" }}
            />
            <p><strong>Name:</strong> {selectedProduct.name}</p>
            <p><strong>Category:</strong> {selectedProduct.category}</p>
            <p><strong>Price:</strong> ₹{selectedProduct.price}</p>
            <p><strong>Brand:</strong> {selectedProduct.brand}</p>
            <button
              className="square-btn delete"
              onClick={() => setShowViewModal(false)}
            >
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
};


export default Products;
